import test from 'node:test';import assert from 'node:assert/strict';
import {journalSections,getJournalEntries} from '../src/journal.js';import {objects,materials} from '../src/data.js';
const entries=(id,found=[],visited=[])=>getJournalEntries(id,new Set(found),new Set(visited),objects,materials);
test('journal has five simple sections and useful empty states',()=>{assert.equal(journalSections.length,5);for(const s of journalSections){assert.ok(s.title&&s.icon&&s.empty);assert.ok(objects.some(o=>o.id===s.target));assert.deepEqual(entries(s.id),[])}});
test('only completed visits and discoveries appear; fossils are not minerals',()=>{assert.deepEqual(entries('minerals',['quartz','iron','fossil']).map(e=>e.id),['quartz','iron']);assert.equal(entries('found',['fossil'])[0].id,'fossil');assert.deepEqual(entries('adventures',[],['dig','plant','crystal']).map(e=>e.id),['plant','crystal']);assert.equal(entries('did',[],['dig','dig']).length,1);assert.equal(entries('did',['quartz'])[0].id,'dig')});
test('station observations do not claim completed experiments; old discoveries stay readable',()=>{assert.deepEqual(entries('experiments',['magnet','crystal']),[]);assert.equal(entries('did',['magnet'])[0].title,'I visited the magnet station.');for(const id of ['did','found','adventures','minerals'])for(const e of entries(id,['plant','rock','quartz','iron','fossil'],['home','dig'])){assert.ok(e.summary&&e.fact&&e.icon);assert.ok(objects.some(o=>o.id===e.target))}});
